import React, { useState, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import api from '../api/axios';
import { updateUser } from '../store/authSlice';
import { Container, Form, Button, Alert, Image } from 'react-bootstrap';

const EditProfile = () => {
  const user = useSelector(state => state.auth.user);
  const roles = useSelector(state => state.auth.roles);
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const isDirector = roles.includes('Директор');

  const [form, setForm] = useState({
    last_name: '',
    first_name: '',
    middle_name: '',
    email: '',
    class: '',
    school_name: '',
    school_address: '',
    school_phone: '',
    school_site: '',
    home_address: '',
    home_phone: '',
    insurance_policy: '',
    blood_type: '',
    medical_contraindications: '',
    parent_full_name: '',
    parent_phone: '',
    position: ''
  });
  const [avatar, setAvatar] = useState(null);
  const [preview, setPreview] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  useEffect(() => {
    if (user) {
      setForm({
        last_name: user.last_name || '',
        first_name: user.first_name || '',
        middle_name: user.middle_name || '',
        email: user.email || '',
        class: user.class || '',
        school_name: user.school_name || '',
        school_address: user.school_address || '',
        school_phone: user.school_phone || '',
        school_site: user.school_site || '',
        home_address: user.home_address || '',
        home_phone: user.home_phone || '',
        insurance_policy: user.insurance_policy || '',
        blood_type: user.blood_type || '',
        medical_contraindications: user.medical_contraindications || '',
        parent_full_name: user.parent_full_name || '',
        parent_phone: user.parent_phone || '',
        position: user.position || ''
      });
      if (user.avatar) {
        setPreview(`http://localhost:8080/uploads/avatars/${user.avatar}`);
      }
    }
  }, [user]);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setAvatar(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreview(reader.result);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    const formData = new FormData();
    Object.keys(form).forEach(key => {
      if (form[key]) formData.append(key, form[key]);
    });
    if (avatar) {
      formData.append('avatar', avatar);
    }

    try {
      const res = await api.put('/user/profile', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      dispatch(updateUser(res.data.user));
      setSuccess('Профиль обновлён!');
      setTimeout(() => navigate('/profile'), 1500);
    } catch (err) {
      setError(err.response?.data?.error || 'Ошибка обновления');
    }
  };

  return (
    <Container className="mt-4">
      <h3>Редактирование профиля</h3>
      {error && <Alert variant="danger">{error}</Alert>}
      {success && <Alert variant="success">{success}</Alert>}
      <Form onSubmit={handleSubmit}>
        {/* Аватар */}
        <Form.Group className="mb-3">
          <Form.Label>Фото</Form.Label>
          {preview && (
            <div className="mb-2">
              <Image src={preview} roundedCircle width="150" height="150" />
            </div>
          )}
          <Form.Control
            type="file"
            accept="image/*"
            onChange={handleFileChange}
          />
        </Form.Group>

        <Form.Group className="mb-2">
          <Form.Label>Фамилия</Form.Label>
          <Form.Control name="last_name" value={form.last_name} onChange={handleChange} />
        </Form.Group>
        <Form.Group className="mb-2">
          <Form.Label>Имя</Form.Label>
          <Form.Control name="first_name" value={form.first_name} onChange={handleChange} />
        </Form.Group>
        <Form.Group className="mb-2">
          <Form.Label>Отчество</Form.Label>
          <Form.Control name="middle_name" value={form.middle_name} onChange={handleChange} />
        </Form.Group>
        <Form.Group className="mb-2">
          <Form.Label>Email</Form.Label>
          <Form.Control name="email" type="email" value={form.email} onChange={handleChange} />
        </Form.Group>

        {/* Скрываем ученические поля для директора */}
        {!isDirector && (
          <>
            <Form.Group className="mb-2">
              <Form.Label>Класс</Form.Label>
              <Form.Control name="class" value={form.class} onChange={handleChange} />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Домашний адрес</Form.Label>
              <Form.Control name="home_address" value={form.home_address} onChange={handleChange} />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Домашний телефон</Form.Label>
              <Form.Control name="home_phone" value={form.home_phone} onChange={handleChange} />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Медицинский полис</Form.Label>
              <Form.Control name="insurance_policy" value={form.insurance_policy} onChange={handleChange} />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Группа крови</Form.Label>
              <Form.Control name="blood_type" value={form.blood_type} onChange={handleChange} />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Медицинские противопоказания</Form.Label>
              <Form.Control as="textarea" rows={2} name="medical_contraindications" value={form.medical_contraindications} onChange={handleChange} />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>ФИО родителей</Form.Label>
              <Form.Control name="parent_full_name" value={form.parent_full_name} onChange={handleChange} />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Телефон родителей</Form.Label>
              <Form.Control name="parent_phone" value={form.parent_phone} onChange={handleChange} />
            </Form.Group>
          </>
        )}

        <Form.Group className="mb-2">
          <Form.Label>Название школы</Form.Label>
          <Form.Control name="school_name" value={form.school_name} onChange={handleChange} />
        </Form.Group>
        <Form.Group className="mb-2">
          <Form.Label>Адрес школы</Form.Label>
          <Form.Control name="school_address" value={form.school_address} onChange={handleChange} />
        </Form.Group>
        <Form.Group className="mb-2">
          <Form.Label>Телефон школы</Form.Label>
          <Form.Control name="school_phone" value={form.school_phone} onChange={handleChange} />
        </Form.Group>
        <Form.Group className="mb-2">
          <Form.Label>Сайт школы</Form.Label>
          <Form.Control name="school_site" value={form.school_site} onChange={handleChange} />
        </Form.Group>

        {user?.position && (
          <Form.Group className="mb-2">
            <Form.Label>Должность</Form.Label>
            <Form.Control name="position" value={form.position} onChange={handleChange} />
          </Form.Group>
        )}
        
        <Button variant="primary" type="submit">Сохранить</Button>
        <Button variant="secondary" className="ms-2" onClick={() => navigate('/profile')}>Отмена</Button>
      </Form>
    </Container>
  );
};

export default EditProfile;
